import{_ as d,c as e,o as t,a8 as c}from"./chunks/framework.jsZJWZJf.js";const o=JSON.parse('{"title":"WebGIS之OpenLayers全面解析（第2版） - 读书笔记","description":"","frontmatter":{"title":"WebGIS之OpenLayers全面解析（第2版） - 读书笔记","outline":[2,2]},"headers":[],"relativePath":"blog/read/books/WebGIS之OpenLayers全面解析（第2版）.md","filePath":"blog/read/books/WebGIS之OpenLayers全面解析（第2版）.md","lastUpdated":1795017144000}'),r={name:"blog/read/books/WebGIS之OpenLayers全面解析（第2版）.md"};function i(b,a,s,n,v,p){return t(),e("div",null,[...a[0]||(a[0]=[c('<div class="social-psychology-notes" data-v-22d4c12b><header class="reading-header" data-v-22d4c12b><h1 data-v-22d4c12b>WebGIS之OpenLayers全面解析（第2版）</h1><p class="reading-byline" data-v-22d4c12b>作者：郭明强 黄颖编著</p><div class="reading-stats" data-v-22d4c12b><span data-v-22d4c12b>12 条摘抄</span><span data-v-22d4c12b>微信读书</span></div></header><section class="reading-book" aria-label="书籍信息" data-v-22d4c12b><div class="reading-cover" data-v-22d4c12b><img src="https://wfqqreader-1252317822.image.myqcloud.com/cover/461/26924461/t6_26924461.jpg" alt="WebGIS之OpenLayers全面解析（第2版）封面" width="160" loading="lazy" data-v-22d4c12b></div><div class="reading-book-info" data-v-22d4c12b><p class="reading-book-title" data-v-22d4c12b>书籍信息</p><dl class="reading-metadata" data-v-22d4c12b><div data-v-22d4c12b><dt data-v-22d4c12b>书名</dt><dd data-v-22d4c12b>WebGIS之OpenLayers全面解析（第2版）</dd></div><div data-v-22d4c12b><dt data-v-22d4c12b>作者</dt><dd data-v-22d4c12b>郭明强 黄颖编著</dd></div><div data-v-22d4c12b><dt data-v-22d4c12b>出版社</dt><dd data-v-22d4c12b>电子工业出版社</dd></div><div data-v-22d4c12b><dt data-v-22d4c12b>出版时间</dt><dd data-v-22d4c12b>2019-09-01 00:00:00</dd></div><div data-v-22d4c12b><dt data-v-22d4c12b>ISBN</dt><dd data-v-22d4c12b>9787121373237</dd></div><div data-v-22d4c12b><dt data-v-22d4c12b>分类</dt><dd data-v-22d4c12b>科学技术-自然科学</dd></div></dl><a class="reading-original-link" href="https://weread.qq.com/web/reader/66232560719ad5ad662c581" target="_blank" rel="noopener noreferrer" data-v-22d4c12b>在微信读书中打开 <span aria-hidden="true" data-v-22d4c12b>↗</span></a><details class="reading-description" data-v-22d4c12b><summary data-v-22d4c12b>书籍简介</summary><p data-v-22d4c12b>作为业内广泛使用的地图引擎之一，OpenLayers已被各大GIS厂商和广大WebGIS二次开发者采用。借助于OpenLayers强大的扩展功能，可以与不同的WebGIS平台产品相结合，开发出各具特色的WebGIS应用系统。 本书的主要内容涵盖WebGIS和OpenLayers的开发基础， OpenLayers的快速入门、多源数据加载、图形绘制、OGC服务、高级功能，最后给出了OpenLayers的项目实战——水利信息在线分析服务系统。</p></details></div></section><h2 id="第2章-webgis开发基础" tabindex="-1" data-v-22d4c12b>第2章 WebGIS开发基础 <a class="header-anchor" href="#第2章-webgis开发基础" aria-label="Permalink to “第2章 WebGIS开发基础”" data-v-22d4c12b>​</a></h2><h3 id="_2-4-webgis开发的gis背景知识" tabindex="-1" data-v-22d4c12b>2.4 WebGIS开发的GIS背景知识 <a class="header-anchor" href="#_2-4-webgis开发的gis背景知识" aria-label="Permalink to “2.4 WebGIS开发的GIS背景知识”" data-v-22d4c12b>​</a></h3><blockquote class="reading-excerpt" id="excerpt-001" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>001</span><div data-v-22d4c12b><p data-v-22d4c12b>矢量数据模型是以对象为单位的，我们可以把一个湖泊的面积等属性都存储在该对象中；而对于栅格数据模型，湖泊是由一组像元组成的，我们不可能将整个湖泊的面积分别赋予每个像元。在实际应用中，大部分地图数据为矢量数据，遥感影像为栅格数据</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-002" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>002</span><div data-v-22d4c12b><p data-v-22d4c12b>矢量地图的加载，是指根据客户端请求的地图范围实时地从服务器的地图数据库中取图，实时生成请求范围对应的地图，这时服务器返回的一张地图。遥感影像与矢量地图采用的是相同的出图机制和方法。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-003" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>003</span><div data-v-22d4c12b><p data-v-22d4c12b>采用级、行、列方式进行组织</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-004" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>004</span><div data-v-22d4c12b><p data-v-22d4c12b>OpenStreetMap（OSM）</p></div></blockquote><h2 id="第3章-openlayers开发基础" tabindex="-1" data-v-22d4c12b>第3章 OpenLayers开发基础 <a class="header-anchor" href="#第3章-openlayers开发基础" aria-label="Permalink to “第3章 OpenLayers开发基础”" data-v-22d4c12b>​</a></h2><blockquote class="reading-excerpt" id="excerpt-005" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>005</span><div data-v-22d4c12b><p data-v-22d4c12b>Canvas渲染和WebGL渲染两种模式的渲染器</p></div></blockquote><h2 id="第4章-openlayers快速入门" tabindex="-1" data-v-22d4c12b>第4章 OpenLayers快速入门 <a class="header-anchor" href="#第4章-openlayers快速入门" aria-label="Permalink to “第4章 OpenLayers快速入门”" data-v-22d4c12b>​</a></h2><h3 id="_4-3-实现地图显示功能" tabindex="-1" data-v-22d4c12b>4.3 实现地图显示功能 <a class="header-anchor" href="#_4-3-实现地图显示功能" aria-label="Permalink to “4.3 实现地图显示功能”" data-v-22d4c12b>​</a></h3><blockquote class="reading-excerpt" id="excerpt-006" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>006</span><div data-v-22d4c12b><p data-v-22d4c12b>在地图容器中，可以针对应用需求设置地图容器背景，即用一张背景图片重复填充，当地图缩放到范围较大时，可避免出现空白，同时还可起到美化作用。</p></div></blockquote><h3 id="_4-4-加载常用控件" tabindex="-1" data-v-22d4c12b>4.4 加载常用控件 <a class="header-anchor" href="#_4-4-加载常用控件" aria-label="Permalink to “4.4 加载常用控件”" data-v-22d4c12b>​</a></h3><blockquote class="reading-excerpt" id="excerpt-007" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>007</span><div data-v-22d4c12b><p data-v-22d4c12b>鼠标位置控件（ol.control.MousePosition）</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-008" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>008</span><div data-v-22d4c12b><p data-v-22d4c12b>比例尺控件（ol.control.ScaleLine）</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-009" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>009</span><div data-v-22d4c12b><p data-v-22d4c12b>鹰眼控件为ol.control.OverviewMap</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-010" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>010</span><div data-v-22d4c12b><p data-v-22d4c12b>全屏显示控件为ol.control.FullScreen</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-011" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>011</span><div data-v-22d4c12b><p data-v-22d4c12b>动画效果由ol.View类的animate方法提供</p></div></blockquote><h2 id="第8章-openlayers之高级功能篇" tabindex="-1" data-v-22d4c12b>第8章 OpenLayers之高级功能篇 <a class="header-anchor" href="#第8章-openlayers之高级功能篇" aria-label="Permalink to “第8章 OpenLayers之高级功能篇”" data-v-22d4c12b>​</a></h2><h3 id="_8-2-投影转换" tabindex="-1" data-v-22d4c12b>8.2 投影转换 <a class="header-anchor" href="#_8-2-投影转换" aria-label="Permalink to “8.2 投影转换”" data-v-22d4c12b>​</a></h3><blockquote class="reading-excerpt" id="excerpt-012" data-v-22d4c12b><span class="reading-excerpt-number" aria-hidden="true" data-v-22d4c12b>012</span><div data-v-22d4c12b><p data-v-22d4c12b>OpenLayers 5已定义了两种常用的投影坐标系，即地理经纬度的EPSG:4326和Web墨卡托的EPSG:3857, EPSG:3857为CRS:84等，EPSG:4326则包括EPSG:102100、EPSG:102113、EPSG:900913。</p></div></blockquote></div>',1)])])}const h=d(r,[["render",i],["__scopeId","data-v-22d4c12b"]]);export{o as __pageData,h as default};
